<?php
require_once 'config/database.php';require_once 'includes/functions.php';
$q=trim($_GET['q']??'');$cat=(int)($_GET['category']??0);$sql="SELECT j.*,c.name category_name,p.full_name FROM jobs j JOIN categories c ON c.id=j.category_id JOIN profiles p ON p.user_id=j.user_id WHERE j.status='open'";$params=[];$like="%$q%";if($q){$sql.=" AND (j.title LIKE ? OR j.description LIKE ? OR j.location LIKE ?)";$params=[$like,$like,$like];}if($cat){$sql.=" AND j.category_id=?";$params[]=$cat;}$sql.=" ORDER BY j.created_at DESC";$st=$pdo->prepare($sql);$st->execute($params);$jobs=$st->fetchAll();$cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();
$pageTitle='Find Jobs';include 'includes/header.php';?>
<section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">OPPORTUNITIES</span><h1>Find jobs & gigs</h1></div><?php if(is_logged_in()):?><a class="btn" href="post-job.php">Post a job</a><?php endif;?></div>
<form class="searchbar"><input name="q" value="<?=e($q)?>" placeholder="Search jobs, skills or location"><select name="category"><option value="">All categories</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="btn">Search</button></form>
<div class="cards"><?php foreach($jobs as $j):?><article class="job-card"><div class="tag"><?=e($j['category_name'])?></div><h3><a href="job.php?id=<?=$j['id']?>"><?=e($j['title'])?></a></h3><p><?=e(mb_strimwidth($j['description'],0,180,'…'))?></p><div class="meta"><span>📍 <?=e($j['location'])?></span><span><?=e(money_range($j['budget_min'],$j['budget_max'],$j['currency']))?></span></div><div class="card-foot"><span><?=e($j['full_name'])?></span><a href="job.php?id=<?=$j['id']?>">Details →</a></div></article><?php endforeach;?></div><?php if(!$jobs):?><div class="empty">No open jobs match your search.</div><?php endif;?></div></section><?php include 'includes/footer.php';?>
